fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Preconditions
    assert!(!x.is_empty(), "Input array x must be non‐empty");
    assert_eq!(x.len(), y.len(), "Input arrays x and y must have the same length");
    assert!(!c.is_empty(), "Coefficient grid c must be non‐empty");
    for (i, row) in c.iter().enumerate() {
        assert!(!row.is_empty(), "Row {} of coefficient grid c must be non‐empty", i);
    }

    // Compute the single default value (either c[0][0] if 1×1, or 0 otherwise)
    let v = default_value(&c);

    // Construct an output vector of the same length as x (and y), filled with v
    vec![v; x.len()]
}

fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // If c is exactly 1×1, return its sole element; otherwise return 0.0
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

